namespace WorkspaceAPIs.Enums;

/// <summary>
/// Defines the type/category of a message within a conversation.
/// </summary>
public enum ConversationMessageTypes
{
    /// <summary>
    /// Message sent by an end user.
    /// </summary>
    User,

    /// <summary>
    /// Message generated by the system or AI assistant.
    /// </summary>
    Bot,

    /// <summary>
    /// Message indicating an error or failure during processing.
    /// </summary>
    Error
}